import json
with open('/app/resources/treasury_bulletin_1953_03.json') as f:
    data = json.load(f)

# Find all elements with content containing relevant dates
for i, elem in enumerate(data['document']['elements']):
    content = elem.get('content')
    if content and isinstance(content, str):
        if '10/3/52' in content or '12/18/52' in content or '12/19/52' in content:
            print(f'Element {i}: type={elem.get(\"type\")}, description={elem.get(\"description\")}')
            # Show relevant part
            lines = content.split('<tr>')
            for j, line in enumerate(lines):
                if '10/3/52' in line or '12/18/52' in line or '12/19/52' in line:
                    print(f'  Line {j}: {line[:200]}')
